package com.wayrapass.service;
import com.wayrapass.dto.request.OperationalRequests;import com.wayrapass.dto.response.OperationalResponses;import com.wayrapass.exception.*;import com.wayrapass.model.*;import com.wayrapass.repository.*;import com.wayrapass.security.CurrentUser;import lombok.RequiredArgsConstructor;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service @RequiredArgsConstructor public class OperationalService{
 private final CurrentUser current;private final TripRepository trips;private final RouteRepository routes;private final RouteScheduleRepository schedules;private final DriverRepository drivers;private final VehicleRepository vehicles;private final StudentRepository students;private final StopRepository stops;private final RouteStopRepository routeStops;private final StudentRouteEnrollmentRepository enrollments;private final BoardingRepository boardings;private final IncidentRepository incidents;private final TripLocationRepository locations;private final NotificationRepository notifications;private final StudentFamilyLinkRepository links;private final AiActionRequestRepository aiRequests;
 @Transactional(readOnly=true) public List<OperationalResponses.Trip> allTrips(){return trips.findAll().stream().map(this::out).toList();}
 @Transactional(readOnly=true) public List<OperationalResponses.Trip> myDriverTrips(){return trips.findByDriverUserId(current.id()).stream().map(this::out).toList();}
 @Transactional public OperationalResponses.Trip createTrip(OperationalRequests.Trip r){if(!r.scheduledEndAt().isAfter(r.scheduledStartAt()))throw new BusinessRuleException("scheduledEndAt debe ser posterior al inicio.");Trip t=new Trip();t.setRoute(routes.findById(r.routeId()).orElseThrow(()->new ResourceNotFoundException("Ruta no encontrada.")));if(r.routeScheduleId()!=null){RouteSchedule sc=schedules.findById(r.routeScheduleId()).orElseThrow(()->new ResourceNotFoundException("Horario no encontrado."));if(!sc.getRoute().getId().equals(r.routeId()))throw new BusinessRuleException("El horario no pertenece a la ruta.");t.setRouteSchedule(sc);}t.setScheduledStartAt(r.scheduledStartAt());t.setScheduledEndAt(r.scheduledEndAt());assign(t,r.driverId(),r.vehicleId(),0L);return out(trips.save(t));}
 @Transactional public OperationalResponses.Trip reassign(Long tripId,OperationalRequests.Reassignment r){Trip t=trips.findByIdForUpdate(tripId).orElseThrow(()->new ResourceNotFoundException("Viaje no encontrado."));assign(t,r.driverId(),r.vehicleId(),t.getId());t.setWasReassigned(true);notifyRoute(t,NotificationType.GENERAL,"Reasignación de viaje","Se actualizaron los recursos asignados al viaje.",null);return out(t);}
 @Transactional public OperationalResponses.Trip status(Long tripId,TripStatus status){Trip t=trips.findByIdForUpdate(tripId).orElseThrow(()->new ResourceNotFoundException("Viaje no encontrado."));User u=current.require();if(u.getRole()!=Role.COORDINATOR&&(t.getDriver()==null||!t.getDriver().getUser().getId().equals(u.getId())))throw new AccessDeniedException("Sin acceso al viaje.");if(status==TripStatus.IN_PROGRESS&&t.getActualStartAt()==null)t.setActualStartAt(Instant.now());if(status==TripStatus.COMPLETED){t.setActualEndAt(Instant.now());if(t.getDriver()!=null)t.getDriver().setOperationalStatus(DriverOperationalStatus.AVAILABLE);if(t.getVehicle()!=null)t.getVehicle().setOperationalStatus(VehicleOperationalStatus.AVAILABLE);}t.setStatus(status);return out(t);}
 private void assign(Trip t,Long driverId,Long vehicleId,Long exclude){if(driverId!=null){Driver d=drivers.findByIdForUpdate(driverId).orElseThrow(()->new ResourceNotFoundException("Conductor no encontrado."));if(d.getAuthorizationStatus()!=AuthorizationStatus.AUTHORIZED||d.getOperationalStatus()!=DriverOperationalStatus.AVAILABLE)throw new BusinessRuleException("El conductor no está autorizado y disponible.");if(trips.driverOverlaps(driverId,t.getScheduledStartAt(),t.getScheduledEndAt(),exclude))throw new ConflictException("El conductor ya tiene un viaje superpuesto.");t.setDriver(d);}if(vehicleId!=null){Vehicle v=vehicles.findByIdForUpdate(vehicleId).orElseThrow(()->new ResourceNotFoundException("Vehículo no encontrado."));if(v.getAuthorizationStatus()!=AuthorizationStatus.AUTHORIZED||v.getOperationalStatus()!=VehicleOperationalStatus.AVAILABLE)throw new BusinessRuleException("El vehículo no está autorizado y disponible.");if(trips.vehicleOverlaps(vehicleId,t.getScheduledStartAt(),t.getScheduledEndAt(),exclude))throw new ConflictException("El vehículo ya tiene un viaje superpuesto.");t.setVehicle(v);}}
 @Transactional public OperationalResponses.Location location(Long tripId,OperationalRequests.Location r){Trip t=ownedTrip(tripId);if(t.getStatus()!=TripStatus.BOARDING&&t.getStatus()!=TripStatus.IN_PROGRESS)throw new BusinessRuleException("Solo se registra ubicación durante un viaje activo.");TripLocation l=new TripLocation();l.setTrip(t);l.setLatitude(r.latitude());l.setLongitude(r.longitude());return out(locations.save(l));}
 @Transactional(readOnly=true) public OperationalResponses.Location latestLocation(Long tripId){return out(locations.findFirstByTripIdOrderByRecordedAtDesc(tripId).orElseThrow(()->new ResourceNotFoundException("El viaje aún no tiene ubicaciones.")));}
 @Transactional public OperationalResponses.Boarding board(OperationalRequests.Boarding r){User u=current.require();Student s=students.findByUserId(u.getId()).orElseThrow(()->new AccessDeniedException("Solo estudiantes."));Trip t=trips.findByIdForUpdate(r.tripId()).orElseThrow(()->new ResourceNotFoundException("Viaje no encontrado."));if(t.getVehicle()==null||!t.getVehicle().getQrToken().equals(r.vehicleQrToken()))throw new BusinessRuleException("El QR no corresponde al vehículo asignado.");if(t.getStatus()!=TripStatus.BOARDING&&t.getStatus()!=TripStatus.IN_PROGRESS)throw new BusinessRuleException("El viaje no admite abordaje.");StudentRouteEnrollment e=enrollments.findByStudentIdAndStatusIn(s.getId(),List.of(EnrollmentStatus.ACTIVE)).filter(x->x.getRoute().getId().equals(t.getRoute().getId())).orElseThrow(()->new BusinessRuleException("El estudiante no pertenece a este viaje."));if(!e.getStop().getId().equals(r.stopId())||!routeStops.existsByRouteIdAndStopId(t.getRoute().getId(),r.stopId()))throw new BusinessRuleException("El paradero no corresponde a la inscripción.");if(boardings.existsByTripIdAndStudentId(t.getId(),s.getId()))throw new ConflictException("El estudiante ya abordó este viaje.");Boarding b=new Boarding();b.setTrip(t);b.setStudent(s);b.setStop(stops.findById(r.stopId()).orElseThrow(()->new ResourceNotFoundException("Paradero no encontrado.")));boardings.save(b);links.findAll().stream().filter(l->l.isAuthorized()&&l.isNotifyBoarding()&&l.getStudent().getId().equals(s.getId())).forEach(l->notify(l.getFamilyUser(),t,NotificationType.BOARDING,"Abordaje confirmado",s.getUser().getFullName()+" abordó el vehículo.",null));return out(b);}
 @Transactional public OperationalResponses.Incident incident(OperationalRequests.Incident r){Trip t=ownedTrip(r.tripId());Incident i=new Incident();i.setTrip(t);i.setDriver(t.getDriver());i.setType(r.type());i.setDescription(r.description());i.setDelayMinutes(r.delayMinutes());i.setPriority(r.priority());incidents.save(i);if(r.delayMinutes()>0){Instant base=t.getEstimatedArrivalAt()!=null?t.getEstimatedArrivalAt():t.getScheduledEndAt();if(base!=null)t.setEstimatedArrivalAt(base.plusSeconds(r.delayMinutes()*60L));}notifyRoute(t,r.delayMinutes()>0?NotificationType.DELAY:NotificationType.INCIDENT,"Incidencia reportada",r.description()==null?r.type().name():r.description(),i);return out(i);}
 @Transactional(readOnly=true) public List<OperationalResponses.Notification> myNotifications(){return notifications.findByRecipientIdOrderByCreatedAtDesc(current.id()).stream().map(this::out).toList();}
 @Transactional public OperationalResponses.AiAction propose(OperationalRequests.AiProposal r){if(r.proposedDriverId()==null&&r.proposedVehicleId()==null)throw new BusinessRuleException("Debe proponerse al menos un recurso.");AiActionRequest a=new AiActionRequest();a.setRequestedBy(current.require());a.setTrip(trips.findById(r.tripId()).orElseThrow(()->new ResourceNotFoundException("Viaje no encontrado.")));a.setActionType(r.actionType());if(r.proposedDriverId()!=null)a.setProposedDriver(drivers.findById(r.proposedDriverId()).orElseThrow(()->new ResourceNotFoundException("Conductor no encontrado.")));if(r.proposedVehicleId()!=null)a.setProposedVehicle(vehicles.findById(r.proposedVehicleId()).orElseThrow(()->new ResourceNotFoundException("Vehículo no encontrado.")));a.setRequestText(r.requestText());a.setAiExplanation(r.aiExplanation());return out(aiRequests.save(a));}
 @Transactional public OperationalResponses.AiAction confirm(Long id){AiActionRequest a=aiRequests.findById(id).orElseThrow(()->new ResourceNotFoundException("Solicitud IA no encontrada."));if(a.getStatus()!=AiActionStatus.PENDING)throw new ConflictException("La solicitud ya fue procesada.");a.setConfirmedBy(current.require());a.setConfirmedAt(Instant.now());a.setStatus(AiActionStatus.CONFIRMED);reassign(a.getTrip().getId(),new OperationalRequests.Reassignment(a.getProposedDriver()==null?null:a.getProposedDriver().getId(),a.getProposedVehicle()==null?null:a.getProposedVehicle().getId()));a.setExecutedAt(Instant.now());a.setStatus(AiActionStatus.EXECUTED);return out(a);}
 private Trip ownedTrip(Long id){Trip t=trips.findByIdForUpdate(id).orElseThrow(()->new ResourceNotFoundException("Viaje no encontrado."));if(t.getDriver()==null||!t.getDriver().getUser().getId().equals(current.id()))throw new AccessDeniedException("El viaje no está asignado al conductor autenticado.");return t;}
 private void notifyRoute(Trip t,NotificationType type,String title,String message,Incident i){for(StudentRouteEnrollment e:enrollments.findByRouteIdAndStatus(t.getRoute().getId(),EnrollmentStatus.ACTIVE)){notify(e.getStudent().getUser(),t,type,title,message,i);for(StudentFamilyLink l:links.findAll())if(l.isAuthorized()&&l.getStudent().getId().equals(e.getStudent().getId()))notify(l.getFamilyUser(),t,type,title,message,i);}}
 private void notify(User u,Trip t,NotificationType type,String title,String message,Incident i){Notification n=new Notification();n.setRecipient(u);n.setTrip(t);n.setIncident(i);n.setType(type);n.setTitle(title);n.setMessage(message);notifications.save(n);}
 private OperationalResponses.Trip out(Trip t){return new OperationalResponses.Trip(t.getId(),t.getRoute().getId(),t.getDriver()==null?null:t.getDriver().getId(),t.getVehicle()==null?null:t.getVehicle().getId(),t.getScheduledStartAt(),t.getScheduledEndAt(),t.getEstimatedArrivalAt(),t.getStatus(),t.isWasReassigned());}private OperationalResponses.Location out(TripLocation l){return new OperationalResponses.Location(l.getId(),l.getTrip().getId(),l.getLatitude(),l.getLongitude(),l.getRecordedAt());}private OperationalResponses.Boarding out(Boarding b){return new OperationalResponses.Boarding(b.getId(),b.getTrip().getId(),b.getStudent().getId(),b.getStop().getId(),b.getBoardedAt());}private OperationalResponses.Incident out(Incident i){return new OperationalResponses.Incident(i.getId(),i.getTrip().getId(),i.getType(),i.getDelayMinutes(),i.getPriority(),i.getStatus(),i.getCreatedAt());}private OperationalResponses.Notification out(Notification n){return new OperationalResponses.Notification(n.getId(),n.getType(),n.getTitle(),n.getMessage(),n.getCreatedAt(),n.getReadAt());}private OperationalResponses.AiAction out(AiActionRequest a){return new OperationalResponses.AiAction(a.getId(),a.getTrip().getId(),a.getActionType(),a.getStatus(),a.getProposedDriver()==null?null:a.getProposedDriver().getId(),a.getProposedVehicle()==null?null:a.getProposedVehicle().getId());}
}
